Un exemple d'un codi en C++ per sumar dos valors sencers i després mostrar-los en la terminal.

#include <iostream>

int main() {
  // Declaració de les variables
  int a, b;
  int suma;

  // Demanar les dades d'entrada a l'usuari
  std::cout << "Introdueix el primer nombre: ";
  std::cin >> a;
  std::cout << "Introdueix el segon nombre: ";
  std::cin >> b;

  // Càlcul de la suma
  suma = a + b;

  // Impressió del resultat a la terminal
  std::cout << "La suma de " << a << " i " << b << " és " << suma << std::endl;

  return 0;
}

```python
from flask import Flask, render_template, request

app = Flask(__name__)

@app.route('/', methods=['GET', 'POST'])
def calculator():
    """
    Handles the main route of the calculator application.
    Renders the calculator form and processes the form submission to perform arithmetic operations.
    Returns the result of the operation or an error message if the input is invalid.
    """
    result = None
    if request.method == 'POST':
        try:
            num1 = float(request.form.get('num1'))
            num2 = float(request.form.get('num2'))
            operation = request.form.get('operation')

            if operation == 'add':
                result = num1 + num2
            elif operation == 'subtract':
                result = num1 - num2
            elif operation == 'multiply':
                result = num1 * num2
            elif operation == 'divide':
                if num2 != 0:
                    result = num1 / num2
                else:
                    return render_template('calculator.html', result='Error: Division by zero!')
        except ValueError:
            return render_template('calculator.html', result='Error: Invalid input. Please enter numbers.')

    return render_template('calculator.html', result=result)

if __name__ == '__main__':
    app.run(debug=True)
```

